function requestRefund(
    address agentToken,
    bytes32 requestId
) external nonReentrant {
    ImageRequest storage request = imageRequests[agentToken][requestId];
    AgentConfig memory config = agentConfigs[agentToken];

    require(request.user == msg.sender, "Not request owner");
    require(request.fulfilled == 0 && request.refunded == 0, "Request already processed");
    require(
        block.timestamp >= request.timestamp + config.refundTimeLimit,
        "Refund time limit not reached"
    );

    request.refunded = block.timestamp;

    // Remove from pending fees
    pendingFees[agentToken] -= request.amount;

    // Transfer tokens back to user
    IERC20Upgradeable(agentToken).safeTransfer(msg.sender, request.amount);

    emit RefundIssued(agentToken, requestId, request.amount);
}

function withdrawFees(address agentToken) external onlyAgentOwner(agentToken) nonReentrant {
    uint256 amount = accumulatedFees[agentToken];
    require(amount > 0, "No fees to withdraw");

    accumulatedFees[agentToken] = 0;
    IERC20Upgradeable(agentToken).safeTransfer(msg.sender, amount);

    emit FeesWithdrawn(agentToken, amount);
}

function requestImage(
    address agentToken,
    string calldata prompt,
    uint256 width,
    uint256 height
) external nonReentrant onlyValidAgent(agentToken) {
    AgentConfig memory config = agentConfigs[agentToken];
    require(config.isConfigured, "Agent not configured");
    require(bytes(prompt).length > 0, "Prompt cannot be empty");
    require(width >= 64 && height >= 64, "Width and height must be greater or equal than 64");
    IERC20Upgradeable token = IERC20Upgradeable(agentToken);

    // Generate request ID from prompt and timestamp
    bytes32 requestId = keccak256(abi.encodePacked(prompt, block.timestamp, msg.sender));

    // Transfer tokens from user to this contract
    token.safeTransferFrom(msg.sender, address(this), config.pricePerImage);

    // Record the request
    imageRequests[agentToken][requestId] = ImageRequest({
        user: msg.sender,
        amount: config.pricePerImage,
        width: width,
        height: height,
        timestamp: block.timestamp,
        fulfilled: 0,
        refunded: 0,
        prompt: prompt
    });

    // Add to pending fees instead of accumulated
    pendingFees[agentToken] += config.pricePerImage;

    emit ImageRequested(agentToken, msg.sender, requestId, config.pricePerImage, width, height, prompt);
}

// Override the transfer function to apply tax only if the recipient is a contract
function transfer(address recipient, uint256 amount) public override returns (bool) {
    // Check if the recipient is agentBalances to prevent recursion
    if (recipient == address(agentBalances)) {
        return super.transfer(recipient, amount);
    }
    address distributor = address(deployer.distributor());
    if (address(deployer) != address(0) &&                               // deployer exists
    (recipient.isContract() || msg.sender.isContract()) &&                   // XOR: exactly one must be a contract
    !(recipient == address(deployer) || msg.sender == address(deployer)) &&  // neither sender nor recipient is deployer
    (distributor == address(0) || recipient != distributor))
    {
        uint256 taxAmount = (amount * taxPercentage) / 10000;
        uint256 amountAfterTax = amount - taxAmount;

        //send the tax to deployer to distribute
        super.transfer(address(deployer), taxAmount);
        deployer.accumulateSwapFees(taxAmount);

        // Transfer the remaining amount to the recipient
        return super.transfer(recipient, amountAfterTax);
    } else {
        // No tax if recipient is not a contract
        return super.transfer(recipient, amount);
    }
}

    enum HedgeOrderType { NONE, MINT, REDEEM }
    enum HedgeOrderStatus { NONE, PENDING, REJECTED, CONFIRMED }

    struct HedgeOrder {
        HedgeOrderType orderType;
        uint256 assetID;
        address redeemToken;
        uint256 nonce;
        uint256 inAmount;
        uint256 outAmount;
        uint256 deadline;
        address requester;
        uint256[5] __gap;
    }

    EnumerableSet.Bytes32Set orderHashs;
    mapping(bytes32 => HedgeOrder) public hedgeOrders;
    mapping(bytes32 => HedgeOrderStatus) public orderStatus;
    mapping(bytes32 => uint256) public requestTimestamps;

    EnumerableSet.UintSet supportAssetIDs;

    address public redeemToken;
    address public orderSigner;
    address public factoryAddress;

    bytes32 public constant PARTICIPANT_ROLE = keccak256("PARTICIPANT_ROLE");

    mapping(bytes32 => bytes32) public redeemTxHashs;

    event AddAssetID(uint256 assetID);
    event RemoveAssetID(uint256 assetID);
    event UpdateOrderSigner(address oldOrderSigner, address orderSigner);
    event UpdateRedeemToken(address oldRedeemToken, address redeemToken);
    event ApplyMint(HedgeOrder hedgeOrder);
    event RejectMint(bytes32 orderHash);
    event ConfirmMint(bytes32 orderHash);
    event ApplyRedeem(HedgeOrder hedgeOrder);
    event RejectRedeem(bytes32 orderHash);
    event ConfirmRedeem(bytes32 orderHash);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address owner, address orderSigner_, address factoryAddress_, address redeemToken_) public initializer {
        __Ownable_init(owner);
        __AccessControl_init();
        __ERC20_init("USSI", "USSI");
        __UUPSUpgradeable_init();
        __Pausable_init();
        require(factoryAddress_ != address(0), "zero factory address");
        require(redeemToken_ != address(0), "zero redeem token address");
        require(orderSigner_ != address(0), "zero order signer address");
        factoryAddress = factoryAddress_;
        redeemToken = redeemToken_;
        orderSigner = orderSigner_;
        _grantRole(DEFAULT_ADMIN_ROLE, owner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}

    function decimals() public pure override(ERC20Upgradeable) returns (uint8) {
        return 8;
    }

    function getSupportAssetIDs() external view returns (uint256[] memory assetIDs) {
        assetIDs = new uint256[](supportAssetIDs.length());
        for (uint i = 0; i < assetIDs.length; i++) {
            assetIDs[i] = supportAssetIDs.at(i);
        }
    }

    function addSupportAsset(uint256 assetID) external onlyOwner {
        require(IAssetFactory(factoryAddress).hasAssetID(assetID), "asset not exists");
        require(!supportAssetIDs.contains(assetID), "already contains assetID");
        supportAssetIDs.add(assetID);
        emit AddAssetID(assetID);
    }

    function removeSupportAsset(uint256 assetID) external onlyOwner {
        require(IAssetFactory(factoryAddress).hasAssetID(assetID), "asset not exists");
        require(supportAssetIDs.contains(assetID), "assetID is not supported");
        supportAssetIDs.remove(assetID);
        emit RemoveAssetID(assetID);
    }

    function updateOrderSigner(address orderSigner_) external onlyOwner {
        address oldOrderSigner = orderSigner;
        require(orderSigner_ != address(0), "orderSigner is zero address");
        require(orderSigner_ != orderSigner, "orderSigner not change");
        orderSigner = orderSigner_;
        emit UpdateOrderSigner(oldOrderSigner, orderSigner);
    }

    function updateRedeemToken(address redeemToken_) external onlyOwner {
        address oldRedeemToken = redeemToken;
        require(redeemToken_ != address(0), "redeem token is zero address");
        require(redeemToken_ != redeemToken, "redeem token not change");
        redeemToken = redeemToken_;
        emit UpdateRedeemToken(oldRedeemToken, redeemToken);
    }

    function checkHedgeOrder(HedgeOrder calldata hedgeOrder, bytes32 orderHash, bytes calldata orderSignature) public view {
        if (hedgeOrder.orderType == HedgeOrderType.MINT) {
            require(supportAssetIDs.contains(hedgeOrder.assetID), "assetID not supported");
        }
        if (hedgeOrder.orderType == HedgeOrderType.REDEEM) {
            require(redeemToken == hedgeOrder.redeemToken, "redeem token not supported");
        }
        require(block.timestamp <= hedgeOrder.deadline, "expired");
        require(!orderHashs.contains(orderHash), "order already exists");
        require(SignatureChecker.isValidSignatureNow(orderSigner, orderHash, orderSignature), "signature not valid");
    }

    function applyMint(HedgeOrder calldata hedgeOrder, bytes calldata orderSignature) external onlyRole(PARTICIPANT_ROLE) whenNotPaused {
        require(hedgeOrder.requester == msg.sender, "msg sender is not requester");
        bytes32 orderHash = keccak256(abi.encode(hedgeOrder));
        checkHedgeOrder(hedgeOrder, orderHash, orderSignature);
        require(hedgeOrder.orderType == HedgeOrderType.MINT, "order type not match");
        HedgeOrder storage hedgeOrder_ = hedgeOrders[orderHash];
        hedgeOrder_.orderType = hedgeOrder.orderType;
        hedgeOrder_.assetID = hedgeOrder.assetID;
        hedgeOrder_.nonce = hedgeOrder.nonce;
        hedgeOrder_.inAmount = hedgeOrder.inAmount;
        hedgeOrder_.outAmount = hedgeOrder.outAmount;
        hedgeOrder_.deadline = hedgeOrder.deadline;
        hedgeOrder_.requester = hedgeOrder.requester;
        orderHashs.add(orderHash);
        orderStatus[orderHash] = HedgeOrderStatus.PENDING;
        requestTimestamps[orderHash] = block.timestamp;
        IERC20 assetToken = IERC20(IAssetFactory(factoryAddress).assetTokens(hedgeOrder.assetID));
        require(assetToken.allowance(hedgeOrder.requester, address(this)) >= hedgeOrder.inAmount, "not enough allowance");
        assetToken.safeTransferFrom(hedgeOrder.requester, address(this), hedgeOrder.inAmount);
        emit ApplyMint(hedgeOrder);
    }

    function rejectMint(bytes32 orderHash) external onlyOwner {
        require(orderHashs.contains(orderHash), "order not exists");
        require(orderStatus[orderHash] == HedgeOrderStatus.PENDING, "order is not pending");
        HedgeOrder storage hedgeOrder = hedgeOrders[orderHash];
        require(hedgeOrder.orderType == HedgeOrderType.MINT, "order type not match");
        orderStatus[orderHash] = HedgeOrderStatus.REJECTED;
        IERC20 assetToken = IERC20(IAssetFactory(factoryAddress).assetTokens(hedgeOrder.assetID));
        assetToken.safeTransfer(hedgeOrder.requester, hedgeOrder.inAmount);
        emit RejectMint(orderHash);
    }

    function confirmMint(bytes32 orderHash) external onlyOwner {
        require(orderHashs.contains(orderHash), "order not exists");
        require(orderStatus[orderHash] == HedgeOrderStatus.PENDING, "order is not pending");
        HedgeOrder storage hedgeOrder = hedgeOrders[orderHash];
        require(hedgeOrder.orderType == HedgeOrderType.MINT, "order type not match");
        _mint(hedgeOrder.requester, hedgeOrder.outAmount);
        orderStatus[orderHash] = HedgeOrderStatus.CONFIRMED;
        IERC20 assetToken = IERC20(IAssetFactory(factoryAddress).assetTokens(hedgeOrder.assetID));
        IAssetIssuer issuer = IAssetIssuer(IAssetFactory(factoryAddress).issuers(hedgeOrder.assetID));
        if (assetToken.allowance(address(this), address(issuer)) < hedgeOrder.inAmount) {
            assetToken.forceApprove(address(issuer), type(uint256).max);
        }
        issuer.burnFor(hedgeOrder.assetID, hedgeOrder.inAmount);
        emit ConfirmMint(orderHash);
    }

    function applyRedeem(HedgeOrder calldata hedgeOrder, bytes calldata orderSignature) external onlyRole(PARTICIPANT_ROLE) whenNotPaused {
        require(hedgeOrder.requester == msg.sender, "msg sender is not requester");
        bytes32 orderHash = keccak256(abi.encode(hedgeOrder));
        checkHedgeOrder(hedgeOrder, orderHash, orderSignature);
        require(hedgeOrder.orderType == HedgeOrderType.REDEEM, "order type not match");
        require(allowance(hedgeOrder.requester, address(this)) >= hedgeOrder.inAmount, "not enough allowance");
        HedgeOrder storage hedgeOrder_ = hedgeOrders[orderHash];
        hedgeOrder_.orderType = hedgeOrder.orderType;
        hedgeOrder_.redeemToken = hedgeOrder.redeemToken;
        hedgeOrder_.nonce = hedgeOrder.nonce;
        hedgeOrder_.inAmount = hedgeOrder.inAmount;
        hedgeOrder_.outAmount = hedgeOrder.outAmount;
        hedgeOrder_.deadline = hedgeOrder.deadline;
        hedgeOrder_.requester = hedgeOrder.requester;
        orderHashs.add(orderHash);
        orderStatus[orderHash] = HedgeOrderStatus.PENDING;
        requestTimestamps[orderHash] = block.timestamp;
        IERC20(address(this)).safeTransferFrom(hedgeOrder.requester, address(this), hedgeOrder.inAmount);
        emit ApplyRedeem(hedgeOrder);
    }

    function rejectRedeem(bytes32 orderHash) external onlyOwner {
        require(orderHashs.contains(orderHash), "order not exists");
        require(orderStatus[orderHash] == HedgeOrderStatus.PENDING, "order is not pending");
        HedgeOrder storage hedgeOrder = hedgeOrders[orderHash];
        require(hedgeOrder.orderType == HedgeOrderType.REDEEM, "order type not match");
        orderStatus[orderHash] = HedgeOrderStatus.REJECTED;
        IERC20(address(this)).safeTransfer(hedgeOrder.requester, hedgeOrder.inAmount);
        emit RejectRedeem(orderHash);
    }

    function confirmRedeem(bytes32 orderHash, bytes32 txHash) external onlyOwner {
        require(orderHashs.contains(orderHash), "order not exists");
        require(orderStatus[orderHash] == HedgeOrderStatus.PENDING, "order is not pending");
        HedgeOrder storage hedgeOrder = hedgeOrders[orderHash];
        require(hedgeOrder.orderType == HedgeOrderType.REDEEM, "order type not match");
        orderStatus[orderHash] = HedgeOrderStatus.CONFIRMED;
        if (txHash == bytes32(0)) {
            require(IERC20(hedgeOrder.redeemToken).balanceOf(address(this)) >= hedgeOrder.outAmount, "not enough redeem token");
            IERC20(hedgeOrder.redeemToken).safeTransfer(hedgeOrder.requester, hedgeOrder.outAmount);
        } else {
            redeemTxHashs[orderHash] = txHash;
        }
        _burn(address(this), hedgeOrder.inAmount);
        emit ConfirmRedeem(orderHash);
    }

    function getOrderHashs() external view returns (bytes32[] memory orderHashs_) {
        orderHashs_ = new bytes32[](orderHashs.length());
        for (uint i = 0; i < orderHashs.length(); i++) {
            orderHashs_[i] = orderHashs.at(i);
        }
    }

    function getOrderHashLength() external view returns (uint256) {
        return orderHashs.length();
    }

    function getOrderHash(uint256 nonce) external view returns (bytes32) {
        return orderHashs.at(nonce);
    }
}

function cancelSwapRequest(OrderInfo memory orderInfo) external onlyRole(TAKER_ROLE) whenNotPaused {
    validateOrderInfo(orderInfo);
    bytes32 orderHash = orderInfo.orderHash;
    require(swapRequests[orderHash].requester == msg.sender, "not order taker");
    require(swapRequests[orderHash].status == SwapRequestStatus.PENDING, "swap request status is not pending");
    require(swapRequests[orderHash].requestTimestamp + MAX_MARKER_CONFIRM_DELAY <= block.timestamp, "swap request not timeout");
    swapRequests[orderHash].status = SwapRequestStatus.CANCEL;
    swapRequests[orderHash].blocknumber = block.number;
    emit CancelSwapRequest(msg.sender, orderHash);
}

function burn(uint amount) external onlyRole(ISSUER_ROLE) {
    _update(msg.sender, address(0), amount);
    Token[] memory newBasket = Utils.subTokenset(basket_, Utils.muldivTokenset(tokenset_, amount, 10 ** decimals()));
    setBasket(newBasket);
}

function addMintRequest(uint256 assetID, OrderInfo memory orderInfo) external whenNotPaused returns (uint) {
    require(_participants[assetID].contains(msg.sender), "msg sender not a participant");
    require(_minAmounts.contains(assetID) && _maxAmounts.contains(assetID), "issue amount range not set");
    require(_issueFees.contains(assetID), "issue fee not set");
    IAssetFactory factory = IAssetFactory(factoryAddress);
    address assetTokenAddress = factory.assetTokens(assetID);
    IAssetToken assetToken = IAssetToken(assetTokenAddress);
    address swapAddress = factory.swap();
    ISwap swap = ISwap(swapAddress);
    require(assetToken.feeCollected(), "has fee not collect");
    require(assetToken.rebalancing() == false, "is rebalancing");
    require(swap.checkOrderInfo(orderInfo) == 0, "order not valid");
    Order memory order = orderInfo.order;
    require(keccak256(abi.encode(assetToken.getTokenset())) == keccak256(abi.encode(order.outTokenset)), "tokenset not match");
    require(order.outAmount >= _minAmounts.get(assetID) && order.outAmount <= _maxAmounts.get(assetID), "mint amount not in range");
    Token[] memory inTokenset = order.inTokenset;
    uint256 issueFee = _issueFees.get(assetID);
    for (uint i = 0; i < inTokenset.length; i++) {
        require(bytes32(bytes(inTokenset[i].chain)) == bytes32(bytes(factory.chain())), "chain not match");
        address tokenAddress = Utils.stringToAddress(inTokenset[i].addr);
        IERC20 inToken = IERC20(tokenAddress);
        uint inTokenAmount = inTokenset[i].amount * order.inAmount / 10**8;
        uint feeTokenAmount = inTokenAmount * issueFee / 10**feeDecimals;
        uint transferAmount = inTokenAmount + feeTokenAmount;
        require(inToken.balanceOf(msg.sender) >= transferAmount, "not enough balance");
        require(inToken.allowance(msg.sender, address(this)) >= transferAmount, "not enough allowance");
        if (inToken.allowance(address(this), swapAddress) < inTokenAmount) {
            inToken.forceApprove(swapAddress, type(uint256).max);
        }
        inToken.safeTransferFrom(msg.sender, address(this), transferAmount);
    }
    swap.addSwapRequest(orderInfo, true, false);
    mintRequests.push(Request({
        nonce: mintRequests.length,
        requester: msg.sender,
        assetTokenAddress: assetTokenAddress,
        amount: order.outAmount,
        swapAddress: swapAddress,
        orderHash: orderInfo.orderHash,
        status: RequestStatus.PENDING,
        requestTimestamp: block.timestamp,
        issueFee: issueFee
    }));
    assetToken.lockIssue();
    emit AddMintRequest(mintRequests.length-1);
    return mintRequests.length-1;
}

function lock(address token, uint256 amount) external whenNotPaused {
    require(tokens_.contains(token), "token not supported");
    require(lockConfigs[token].epoch == activeEpochs[token], "token cannot stake now");
    LockData storage lockData = lockDatas[token][msg.sender];
    LockConfig storage lockConfig = lockConfigs[token];
    require(lockConfig.totalLock + amount <= lockConfig.lockLimit, "total lock amount exceeds lock limit");
    require(IERC20(token).allowance(msg.sender, address(this)) >= amount, "not enough allowance");
    lockData.amount += amount;
    lockConfig.totalLock += amount;
    IERC20(token).transferFrom(msg.sender, address(this), amount);
    emit Lock(msg.sender, token, amount);
}

