/**
 * @notice Receive function - Receives Funds.

/**
 * @notice Burns 20% of the ETH balance and uses the rest to buy LINEA tokens which are then bridged to L1 to be burned.
 * @param _swapData Encoded calldata for the DEX swap function.
 */
function burnAndBridge(bytes calldata _swapData) external onlyRole(BURNER_ROLE) {
  _payArrears();

  uint256 minimumFee = messageService.minimumFeeInWei();

  if (address(this).balance > minimumFee) {
    uint256 balanceAvailable = address(this).balance - minimumFee;

    uint256 ethToBurn = (balanceAvailable * ETH_BURNT_PERCENTAGE) / 100;
    (bool success, ) = address(0).call{ value: ethToBurn }("");
    require(success, EthBurnFailed());

    (bool swapSuccess, ) = dexSwapAdapter.call{ value: balanceAvailable - ethToBurn }(_swapData);
    require(swapSuccess, DexSwapFailed());

    address lineaTokenAddress = lineaToken;
    TokenBridge tokenBridgeContract = tokenBridge;

    uint256 lineaTokenBalanceAfter = IERC20(lineaTokenAddress).balanceOf(address(this));

    IERC20(lineaTokenAddress).approve(address(tokenBridgeContract), lineaTokenBalanceAfter);

    tokenBridgeContract.bridgeToken{ value: minimumFee }(
      lineaTokenAddress,
      lineaTokenBalanceAfter,
      l1LineaTokenBurner
    );

    emit EthBurntSwappedAndBridged(ethToBurn, lineaTokenBalanceAfter);
  }
}

function updateBlockHashProverCopy(RemoteReadArgs calldata bhpPointerReadArgs, IBlockHashProver bhpCopy)
    external
    returns (bytes32 bhpPointerId)
{
    uint256 slot;
    bytes32 bhpCodeHash;
    (bhpPointerId, slot, bhpCodeHash) = _readRemoteSlot(bhpPointerReadArgs);

    if (slot != uint256(BLOCK_HASH_PROVER_POINTER_SLOT)) {
        revert WrongBlockHashProverPointerSlot();
    }

    if (address(bhpCopy).codehash != bhpCodeHash) {
        revert DifferentCodeHash();
    }

    IBlockHashProver oldProverCopy = _blockHashProverCopies[bhpPointerId];

    if (oldProverCopy.version() >= bhpCopy.version()) {
        revert NewerProverVersion();
    }

    _blockHashProverCopies[bhpPointerId] = bhpCopy;
}

/**
 * @notice Sets an immutable map between 2 chain identifiers.
 * @dev Can only be called once for every chain.
 * @param protocolChainIdentifier Messaging protocol's chain identifier.
 * @param chainId "Canonical" chain id. For EVM, should be block.chainid.
 */
function setChainMap(
    uint256 protocolChainIdentifier,
    uint256 chainId
) external onlyOwner {
    if (protocolChainIdentifier == 0) revert ZeroValue();
    if (chainId == 0) revert ZeroValue();

    if (chainIdMap[protocolChainIdentifier] != 0) revert AlreadySet();
    if (reverseChainIdMap[chainId] != 0) revert AlreadySet();

    chainIdMap[protocolChainIdentifier] = chainId;
    reverseChainIdMap[chainId] = protocolChainIdentifier;

    emit ChainMapConfigured(protocolChainIdentifier, chainId);
}

