function participate(
    uint256 pointAmt,
    uint256 virtualsAmt,
    address userAddress
)
    external
    nonReentrant
    whenNotCancelled
    whenNotFailed
    whenStarted
    whenNotEnded
{
    require(pointAmt > 0, "Point amount must be greater than 0");
    require(virtualsAmt > 0, "Virtuals must be greater than 0");

    // Check single submission upper limit
    require(
        virtualsAmt <= maxContributionVirtualAmount,
        "Exceeds maximum virtuals per contribution"
    );

    // Add balance check
    require(
        IERC20(virtualTokenAddress).balanceOf(msg.sender) >= virtualsAmt,
        "Insufficient Virtual Token balance"
    );
    // Add allowance check
    require(
        IERC20(virtualTokenAddress).allowance(msg.sender, address(this)) >=
            virtualsAmt,
        "Insufficient Virtual Token allowance"
    );

    // Update participant list
    if (mapAddrToVirtuals[userAddress] == 0) {
        participants.push(userAddress);
    }

    // Update state
    mapAddrToVirtuals[userAddress] += virtualsAmt;

    IERC20(virtualTokenAddress).safeTransferFrom(
        msg.sender,
        address(this),
        virtualsAmt
    );

    emit Participated(genesisId, userAddress, pointAmt, virtualsAmt);
}

function onGenesisFailed()
    external
    onlyRole(FACTORY_ROLE)
    nonReentrant
    whenNotCancelled
    whenNotFailed
    whenTokenNotLaunched
    whenEnded
{
    isFailed = true;

    // Return all virtuals to participants
    for (uint256 i = 0; i < participants.length; i++) {
        address participant = participants[i];
        uint256 virtualsAmt = mapAddrToVirtuals[participant];
        if (virtualsAmt > 0) {
            // first clear the virtuals mapping of the user to prevent reentrancy attacks
            mapAddrToVirtuals[participant] = 0;
            // then transfer the virtuals
            IERC20(virtualTokenAddress).safeTransfer(
                participant,
                virtualsAmt
            );
            emit RefundClaimed(genesisId, participant, virtualsAmt);
        }
    }

    emit GenesisFinalized(genesisId, false);
}

/**
 * @notice Internal function for registering an allocator. Validates that one of three
 * conditions is met: caller is the allocator address, allocator address contains code, or
 * proof represents valid create2 deployment parameters that derive the allocator address.
 * @param allocator    The address to register as an allocator.
 * @param proof        An 85-byte value containing create2 address derivation parameters.
 * @return allocatorId A unique identifier assigned to the registered allocator.
 */
function _registerAllocator(address allocator, bytes calldata proof) internal returns (uint96 allocatorId) {
    allocator = uint256(uint160(allocator)).asSanitizedAddress();
    if (!allocator.canBeRegistered(proof)) {
        assembly ("memory-safe") {
            // revert InvalidRegistrationProof(allocator)
            mstore(0, 0x4e7f492b)
            mstore(0x20, allocator)
            revert(0x1c, 0x24)
        }
    }

    allocatorId = allocator.register();
}

